class Solution:
    def numSubarrayProductLessThanK(self, nums: list[int], k: int) -> int:
        if k <= 1:
            return 0
        ans = 0
        n = len(nums)
        for i in range(n):
            prod = 1
            for j in range(i, n):
                prod *= nums[j]
                if prod >= k:
                    break
                ans += 1
        return ans

